create or replace function register_schedule_compute_worker_v1(p_worker_key text,p_display_name text,p_worker_type text,p_capabilities jsonb default '{}',p_max_parallel smallint default 1,p_cpu_threads smallint default null,p_gpu_model text default null,p_gpu_memory_mb integer default null,p_software_version text default null) returns uuid language plpgsql security definer set search_path=public as $$declare x uuid;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;if p_worker_type not in('CPU','GPU') then raise exception 'WORKER_TYPE_INVALID';end if;insert into schedule_compute_workers(worker_key,display_name,worker_type,capabilities,max_parallel,health,priority,last_heartbeat,connection_mode,cpu_threads,gpu_model,gpu_memory_mb,software_version) values(p_worker_key,p_display_name,p_worker_type,coalesce(p_capabilities,'{}'),greatest(1,p_max_parallel),'HEALTHY',case when p_worker_type='GPU' then 2 else 5 end,now(),'PULL',p_cpu_threads,p_gpu_model,p_gpu_memory_mb,p_software_version) on conflict(worker_key) do update set display_name=excluded.display_name,worker_type=excluded.worker_type,capabilities=excluded.capabilities,max_parallel=excluded.max_parallel,health='HEALTHY',last_heartbeat=now(),cpu_threads=excluded.cpu_threads,gpu_model=excluded.gpu_model,gpu_memory_mb=excluded.gpu_memory_mb,software_version=excluded.software_version,active=true,updated_at=now() returning id into x;return x;end$$;
create or replace function import_local_schedule_candidate_v1(p_rows jsonb,p_title text default 'Yerel hızlandırıcı adayı') returns uuid language plpgsql security definer set search_path=public as $$declare sid uuid:=gen_random_uuid();grp uuid:=gen_random_uuid();rev bigint;bad int;sc int;r record;begin perform open_permission_context('schedule.generate');if current_tenant_code() is null then raise exception 'TENANT_CONTEXT_REQUIRED';end if;if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)=0 then raise exception 'EMPTY_CANDIDATE';end if;select revision into rev from schedule_engine_state where id=true;insert into schedule_scenarios(id,generation_group,scenario_no,title,basis_revision,institution_code,status) values(sid,grp,1,coalesce(nullif(p_title,''),'Yerel hızlandırıcı adayı'),rev,current_tenant_code(),'generated');for r in select * from jsonb_to_recordset(p_rows) as x(assignment_id uuid,weekday smallint,period smallint,classroom_id uuid,subgroup_id uuid,locked boolean) loop insert into schedule_scenario_rows(scenario_id,requirement_id,teacher_assignment_id,teacher_id,class_id,weekday,period,class_name,subject,classroom_id,subgroup_id,subgroup_key,is_group_split,locked,course_id,institution_code) select sid,req.id,a.id,a.teacher_id,req.class_id,r.weekday,r.period,c.class_name,cc.name,r.classroom_id,r.subgroup_id,sg.subgroup_key,r.subgroup_id is not null,coalesce(r.locked,false),req.course_id,current_tenant_code() from teacher_course_assignments a join class_course_requirements req on req.id=a.class_course_requirement_id join school_classes c on c.id=req.class_id join course_catalog cc on cc.id=req.course_id left join class_subgroups sg on sg.id=r.subgroup_id and sg.class_id=req.class_id where a.id=r.assignment_id and a.institution_code=current_tenant_code();if not found then raise exception 'CANDIDATE_ASSIGNMENT_INVALID';end if;end loop;perform * from assign_classrooms_to_scenario_permission_core_v2(sid);bad:=validate_schedule_scenario_v2(sid);sc:=rescore_schedule_scenario_v2(sid);update schedule_scenarios set row_count=(select count(*) from schedule_scenario_rows where scenario_id=sid),score=sc,status=case when bad=0 then 'generated' else 'invalid' end where id=sid;perform refresh_schedule_repair_suggestions_v1(sid);return sid;exception when others then delete from schedule_scenarios where id=sid;raise;end$$;
create or replace function accept_schedule_worker_result_v1(p_attempt_id uuid) returns uuid language plpgsql security definer set search_path=public as $$declare payload jsonb;tenant text;sid uuid;begin perform open_permission_context('schedule.generate');select a.result_payload,j.institution_code into payload,tenant from schedule_solve_attempts a join schedule_solve_jobs j on j.id=a.job_id where a.id=p_attempt_id and a.status='COMPLETED';if tenant is null then raise exception 'WORKER_RESULT_NOT_READY';end if;if tenant<>current_tenant_code() then raise exception 'TENANT_MISMATCH';end if;sid:=import_local_schedule_candidate_v1(payload->'rows','CPU/GPU Worker Adayı');update schedule_solve_attempts set scenario_id=sid,score=(select score from schedule_scenarios where id=sid),hard_issue_count=(select coalesce(sum(affected_count),0) from schedule_scenario_integrity_issues where scenario_id=sid),unplaced_count=(select count(*) from schedule_unplaced_items where scenario_id=sid) where id=p_attempt_id;return sid;end$$;